package com.course.platform.service.impl;

import com.course.platform.common.exception.BusinessException;
import com.course.platform.domain.dto.OrderCreateRequest;
import org.junit.jupiter.api.*;
import java.time.Duration;
import static org.junit.jupiter.api.Assertions.*;

/** 普通价必须独立确认原冻结政策，只扣普通余额，原专户和过期旧调用仍保留。 */
class CoursePrivateGeneralCheckoutTransactionTest {
    CoursePrivateTermLifecycleTransactionTest f;
    com.course.platform.application.service.order.CourseOrderService orders;
    CoursePricingService pricing;
    @BeforeEach void setup() throws Exception {f=new CoursePrivateTermLifecycleTransactionTest();f.setup();f.config.getRules().setAllowGeneralCheckout(true);f.seed();f.enroll();f.deposit("100","first");f.products.selectById(9L).setBasePrice(new java.math.BigDecimal("10"));f.products.selectById(9L).setRateType("MULTIPLY");f.f.jdbc.update("UPDATE sys_user SET rate=1 WHERE id=7");orders=f.orderService();pricing=f.pricingContext.getBean(CoursePricingService.class);org.springframework.test.util.ReflectionTestUtils.setField(f.service,"generalCheckoutEnabled",true);}
    @AfterEach void clear(){f.clear();}
    void expire(){f.clock.advance(Duration.ofDays(30));}
    OrderCreateRequest ordinary(String key){var offer=pricing.preview(7L,9L).ordinaryOffer();assertNotNull(offer);var r=f.orderRequest(key);r.setCheckoutIntent("GENERAL_EXPLICIT");r.setExpectedAmount(offer.finalPrice());r.setExpectedContractVersion(offer.contractVersion());r.setExpectedPriceSource("RATE");r.setExpectedPaymentSource("GENERAL");r.setExpectedPolicyTermId(offer.policyTermId());r.setExpectedPolicyVersionId(offer.policyVersionId());return r;}
    @Test void expiredDefaultStillRejectsAndExplicitOrderPreservesSources(){expire();assertThrows(BusinessException.class,()->orders.createOrder(f.orderRequest("default"),7L));var r=ordinary("explicit");Long id=orders.createOrder(r,7L);var row=f.orderRows.selectById(id);assertEquals("RATE",row.getPriceSource());assertEquals("GENERAL",row.getPaymentSource());assertNull(row.getPrivateContractId());assertNull(row.getPrivateTermId());assertNull(row.getWalletId());f.f.money("390",f.f.balance("sys_user",7));f.f.money("100",f.wallet().getBalance());assertEquals(id,orders.createOrder(r,7L));}
    @Test void activeInsufficientWalletNeverOffersOrdinaryFallback(){f.f.jdbc.update("UPDATE course_reserved_wallet SET balance=0 WHERE contract_id=?",f.current().getContractId());assertNull(pricing.preview(7L,9L).ordinaryOffer());var r=f.orderRequest("active_fallback");r.setCheckoutIntent("GENERAL_EXPLICIT");assertThrows(BusinessException.class,()->orders.createOrder(r,7L));}
    @Test void policyChangeAndMissingBindingsCannotUsePriorConfirmation(){expire();var r=ordinary("changed");f.f.jdbc.update("UPDATE course_private_contract SET version=version+1");assertThrows(BusinessException.class,()->orders.createOrder(r,7L));var missing=ordinary("missing");missing.setExpectedPolicyVersionId(null);assertThrows(BusinessException.class,()->orders.createOrder(missing,7L));}
    @Test void flagsAndFrozenRuleMustBothAllowOffer() throws Exception {expire();org.springframework.test.util.ReflectionTestUtils.setField(f.service,"generalCheckoutEnabled",false);assertNull(pricing.preview(7L,9L).ordinaryOffer());org.springframework.test.util.ReflectionTestUtils.setField(f.service,"generalCheckoutEnabled",true);f.config.getRules().setAllowGeneralCheckout(false);f.f.jdbc.update("UPDATE course_private_contract_term SET config_snapshot=? WHERE id=?",f.json.writeValueAsString(f.config),f.current().getId());assertNull(pricing.preview(7L,9L).ordinaryOffer());}
    @Test void confirmationCannotSurviveFlagClosureOrRestoredPrivateRights(){expire();var closed=ordinary("flag_closed");org.springframework.test.util.ReflectionTestUtils.setField(f.service,"generalCheckoutEnabled",false);assertThrows(BusinessException.class,()->orders.createOrder(closed,7L));org.springframework.test.util.ReflectionTestUtils.setField(f.service,"generalCheckoutEnabled",true);f.clock.advance(Duration.ofDays(-29));f.f.jdbc.update("UPDATE course_private_contract SET status='SUSPENDED',version=version+1");var suspended=ordinary("resumed");f.f.jdbc.update("UPDATE course_private_contract SET status='ACTIVE',version=version+1");assertThrows(BusinessException.class,()->orders.createOrder(suspended,7L));f.f.money("400",f.f.balance("sys_user",7));f.f.money("100",f.wallet().getBalance());}
    @Test void generalRefundReturnsToOriginalGeneralBalanceOnly(){expire();Long id=orders.createOrder(ordinary("refund_general"),7L);var general=(AccountLedgerServiceImpl)org.springframework.test.util.ReflectionTestUtils.getField(f.f.service,"generalLedger");var payment=new CourseOrderPaymentService(general,f.f.service,f.orderRows);f.f.tx.executeWithoutResult(tx->payment.refund(f.orderRows.selectById(id),8L));f.f.money("400",f.f.balance("sys_user",7));f.f.money("100",f.wallet().getBalance());assertNotNull(f.orderRows.selectById(id).getRefundedAt());}
    @Test void oldRequestFingerprintRemainsByteCompatible() throws Exception {var r=f.orderRequest("old_fingerprint");String old=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(java.util.Arrays.asList(r.getPlatformId(),r.getSchoolName(),r.getStudentName(),r.getStudentAccount(),r.getStudentPassword(),r.getCourseId(),r.getCourseName(),Boolean.TRUE.equals(r.getIsFastMode()),null,null,null,null));assertEquals(com.course.platform.common.security.TokenHashUtil.sha256(old),CourseOrderRequestIdentity.fingerprint(r));}
    @Test void intentChangesCannotAdoptExistingSuccessfulRequest(){expire();var r=ordinary("identity");orders.createOrder(r,7L);r.setCheckoutIntent(null);assertThrows(BusinessException.class,()->orders.createOrder(r,7L));}
}
